import com.example.lending.domain.Loan;

class LoanMapper {

    LoanJpaEntity toEntity(Loan loan) {
        CreditCheck creditCheck = loan.getCreditCheck();
        CreditCheckEmbeddable embeddable = new CreditCheckEmbeddable(creditCheck.approved(), creditCheck.score(),
                creditCheck.reasonCodes(), creditCheck.checkedAt(), creditCheck.providerName(),
                creditCheck.providerVersion());
        return new LoanJpaEntity(loan.getId(), loan.getBookId(), loan.getMemberId(), loan.getLoanedAt(), loan.getDueAt(),
                loan.getReturnedAt(), embeddable);
