        CreditCheck creditCheck = new CreditCheck(embeddable.isApproved(), embeddable.getScore(),
                embeddable.getReasonCodes(), embeddable.getCheckedAt(), embeddable.getProviderName(),
                embeddable.getProviderVersion());
        return Loan.reconstitute(entity.getId(), entity.getBookId(), entity.getMemberId(), entity.getLoanedAt(),
                entity.getDueAt(), entity.getReturnedAt(), creditCheck);
    }
}

